h$::jsonb) as item;
do $guard$ begin
 if (select count(*) from reviewed_self_host_p) <> 10 then raise exception 'P review must contain ten rows'; end if;
 if (select count(*) from reviewed_self_host_p r join public.self_host_apps a on a.id=(r.item->>'app_id')::uuid and a.slug=r.item->>'slug' where a.published and a.self_hosting_status='self_hostable' and a.name is not distinct from r.item#>>'{current,name}' and a.source_code_url is not distinct from r.item#>>'{current,source_code_url}' and a.docker_image is not distinct from r.item#>>'{current,docker_image}') <> 10 then raise exception 'P snapshot changed since review'; end if;
 if exists (select 1 from reviewed_self_host_p r cross join lateral jsonb_array_elements_text(r.item#>'{verified,categories}') c(slug) left join public.self_host_app_categories cat on cat.slug=c.slug where cat.id is null) then raise exception 'P review contains unknown category'; end if;
end $guard$;
update public.self_host_apps a set published=false,updated_at=now() from reviewed_self_host_p r where a.id=(r.item->>'app_id')::uuid and r.item->>'directory_action' like 'unpublish%';
update public.self_host_apps a set
 name=v->>'name',summary=v->>'summary',summary_source=coalesce(v->>'docs_url',v->>'website_url',v->>'source_code_url'),summary_confidence='high',
