 license=v->>'license',license_type=(v->>'license_type')::public.self_host_app_license_type,license_spdx_id=v->>'license_spdx_id',
 publisher_name=v->>'publisher_name',publisher_type=v->>'publisher_type',publisher_url=v->>'publisher_url',docs_url=v->>'docs_url',install_docs_url=v->>'install_docs_url',docker_support=v->>'docker_support',docker_url=v->>'docker_url',docker_image=v->>'docker_image',
 compose_support=nullif(v->>'compose_support','')::boolean,compose_url=v->>'compose_url',requires_database=nullif(v->>'requires_database','')::boolean,database_types=array(select jsonb_array_elements_text(coalesce(v->'database_types','[]'::jsonb))),storage_profile=v->>'storage_profile',persistent_storage=nullif(v->>'persistent_storage','')::boolean,
 deployment_methods=array(select jsonb_array_elements_text(coalesce(v->'deployment_methods','[]'::jsonb))),maintenance_status=v->>'maintenance_status',release_version=v->>'release_version',release_url=v->>'release_url',release_checked_at=now(),
 data_source_urls=array(select jsonb_array_elements_text(r.item->'sources')),data_checked_at=now(),data_confidence='high',technical_facts_checked_at=now(),
 github_owner=case when v->>'source_code_host'='github' then split_part(v->>'source_full_name','/',1) else null end,github_repo=case when v->>'source_code_host'='github' then split_part(v->>'source_full_name','/',2) else null end,github_full_name=case when v->>'source_code_host'='github' then v->>'source_full_name' else null end,
