do $verify$ begin
 if (select count(*) from reviewed_self_host_p r join public.self_host_apps a on a.id=(r.item->>'app_id')::uuid join public.self_host_app_resource_estimates e on e.app_id=a.id join public.self_host_app_install_options io on io.app_id=a.id where r.item->>'directory_action'='retain' and a.published and a.data_checked_at::date=current_date and e.ram_estimate_kind='estimated' and e.storage_estimate_kind='estimated' and jsonb_array_length(io.options)>0) <> 7 then raise exception 'P retained records not fully updated'; end if;
 if (select count(*) from reviewed_self_host_p r join public.self_host_apps a on a.id=(r.item->>'app_id')::uuid where r.item->>'directory_action' like 'unpublish%' and not a.published) <> 3 then raise exception 'P duplicates were not unpublished'; end if;
end $verify$;
